  "想只放大某一块面板？鼠标指着那块面板，按 Ctrl 滚轮 —— 那是这块面板自己的缩放，各块互不影响，也不会挤动旁边的布局。": "Zoom a single panel? Hover over it and Ctrl+Wheel — zoom is per-panel and isolated.",
