  "人力资源部": "HR Dept",
  "实时计费：把整个软件里的 API 用量按自然日归档、按模型算成钱，可打分支比较两段工作流各自的花费 —— 面板只是它的显示器": "Real-time billing: archive daily API token usage and calculate costs per model.",
  "看护本机那台模型桥接（CLIProxyAPI）：软件启动时确认它在不在，不在就自动拉起来": "Guard local model bridge (CLIProxyAPI): check status on startup and auto-launch if offline.",
  "连 ComfyUI：看队列与模型、管命名工作流、拿提示词出图并把图存回工作区": "Connect ComfyUI: monitor queue/models, manage workflows, and generate images to workspace.",
  "上下文压缩：把旧对话写成前情纪要（/compress）。压缩哪个模型由参数指定，挑个便宜的": "Context compression: summarize earlier messages (/compress) using configured model.",
  "给这个软件增加一个新工具（助手能调用的新能力），或者改现有工具的行为时看这份": "Instructions for adding or updating tools that the assistant can invoke.",
  "用 ComfyUI 出图：先探服务、按需起服务（本机或远程）、挑真有的模型、管命名工作流；出图时对话里会自己出现进度容器和过程草稿图，成品图直接落在回复里": "Generate images with ComfyUI: auto-connect, workflow selection, progress container & preview.",
  "这个软件自身的接线地图：系统提示、工具表、面板类型、技能、插件各在哪": "Internal architecture map: system prompts, tools, panel types, skills, and plugins.",
  "构建失败、改完代码界面没反应、报错看不懂时，按这个顺序排查": "Fix build errors, hot-reload failures, or compile issues in recommended order.",
  "新建或改造插件、给插件加面板类型、往核心加内置面板之前，先看这份规范 —— 东西该放哪、三件套怎么接、状态/命令文件怎么走、挂件（floatBare / 鼠标穿透）、面板隔离（几块面板不许串味）、收尾四步": "Plugin specification: file locations, API hooks, state contracts, and panel isolation.",
  "被声明过的面板都在这儿，关不关都在。": "Declared panels stay here, whether closed or open.",
  "（顶栏、标题一起跟着变）。「收进收纳区」只是让它在顶栏占一格，跟声明不是一回事；「克隆一个」是照它再开一块新的。": " (top bar & title sync together).release/stow is not declaration; \"Clone\" opens a new instance.",
  "，连那份对话记录一起没。": ", permanently deleting that conversation history.",
  "按需取用的说明。系统提示里只带名字和一句话，助手觉得对得上才用": "On-demand instructions. The system prompt only carries the name and one sentence;",
  "正文 —— 所以技能写多长都不占日常开销。": " full body is retrieved via use_skill, saving token overhead.",
  "给助手加工具的扩展：": "Extensions that grant tools to assistant:",
  "，CommonJS。能注册新工具（todo / jobs / web 就是插件），也能挂在写文件之前 —— 内置的 file-backup 靠这一手，每次改写前自动留底。插件改完不用重启：下一次对话就会用新代码。": ", CommonJS. Registers new tools and hooks before file writes (e.g. file-backup snapshot). Hot-reloads on next turn.",
  "本机存着 {n} components, plus more in the workspace {m} 份做法": "Local components: {n}, workspace crafts: {m}",
  "份做法": "crafts",
  "命中输入    {n}    {sym}{c}": "Hit in:     {n}    {sym}{c}",
