  "单价 {a} / {b} / {c} 元每百万（命中 / 未命中 / 输出）": "Price: ${a} / ${b} / ${c} per 1M (Hit / Miss / Out)",
  "{a} 轮 · {b} 轮已计费": "{a} turns · {b} billed",
  "本机存着 {n} 份组件、工作区里还有 {m} 份做法": "Local components: {n}, workspace crafts: {m}",
  "两处都是空的 —— 多半是工作区指错了。": "Both are empty — workspace path might be wrong.",
  " · 跟着仓库来的": " · From repo",
  " · 挂在顶上收纳区": " · Pinned in bar",
