  "⚠ 接口发来的工具调用没带工具名，没法执行，这一步空了。说「重试」再来一次。": "⚠ The tool call came back from the API without a tool name, so it can't run and this step was skipped. Say \"Retry\" to try again.",
  "⚠ 这次回复被输出长度上限截断了，还没说完。说「继续」我把剩下的补完。": "⚠ This reply was cut off by the output length limit and isn't finished. Say \"Continue\" and I'll finish the rest.",
  "关掉就落在这儿 —— 不管它是对话、表格还是番茄钟。": "Close it and it lands here — whether it's a conversation, a table, or a pomodoro.",
  "关掉不是删掉：连同它那整段对话记录一起留着，本体在": "Closing is not deleting: kept together with the whole conversation record, stored in ",
  "（声明过的那些关闭时回组件库、不进这儿 —— 哪怕它没挂到顶栏。）": " (Declared ones return to the component library on close instead of here — even if not pinned to the top bar.)",
  "名字": "name",
  "[... 工具结果的中间部分已修剪 ...]": "[... Middle of the tool result trimmed ...]",
  "只输出一行，格式：标题｜关键词1,关键词2": "Output one line only, format: Title｜Keyword1,Keyword2",
  "。组件、做法、技能全是按工作区找的 ——": ". Components, recipes, and skills are all looked up by workspace —",
  "正在启动后台安装任务并连接镜像加速...": "Starting the background install task and connecting to the mirror accelerator...",
  "（峰谷段也在里头加，想开几条开几条）；": "(peak and valley windows go in there too — open as many as you like);",
  "想让它接着做，直接把这句话发出去就行。": "To let it keep going, just send this message as is.",
  "—— 想瘦身只能在这一页手动删除。": " — To slim down, you can only delete things by hand on this page.",
  "（顶栏、标题一起跟着变）。": "(the top bar and title change along with it).",
  "[完成] 成功安装并就绪:": "[Done] Installed and ready:",
  "[错误] 下载安装失败:": "[Error] Download and install failed:",
  "，工作区现在却指着": ", but the workspace now points to",
  "，重启也还在。": ", and it survives a restart.",
  "有参数可调 ·": "Adjustable params ·",
  "没参数可调 ·": "No params ·",
  "[安装失败]:": "[Install failed]:",
  "正文读不出来：": "Couldn't read the body:",
  "【运行时快照】": "[Runtime snapshot]",
  "[异常]": "[Exception]",
  "取正文": "Fetch body",
  "面板：": "Panel:",
  "这行是明牌：python 环境不对 —— 要用 ComfyUI 自己那个 venv / 桌面版自带的解释器。": "This line says it outright: the python environment is wrong — use ComfyUI's own venv / the interpreter that ships with the desktop app.",
  "也确认一下端口：命令行版默认 8188，ComfyUI Desktop 默认 **8000** ——": "Also check the port: the command-line version defaults to 8188, ComfyUI Desktop defaults to **8000** —",
  "崩坏／糊／空白／不是要的东西，就自己改提示词或换 seed 重画（最多重画两次）；没问题就别折腾。": "Broken / blurry / blank / not what you asked for — edit the prompt or change the seed and regenerate (at most twice); if it's fine, leave it alone.",
  "这行是明牌：那个端口已经被别的进程占了 —— 换一个 --port，或者先把占着它的关掉。": "This line says it outright: that port is already taken by another process — use a different --port, or shut down whatever is holding it.",
  "参数里没配「关闭命令」，我不知道怎么把它关掉。想让我能关，就在 stop 里填一条，例如：": "No \"stop command\" is configured in the params, so I don't know how to shut it down. To let me stop it, fill one in under stop, e.g.:",
  "动手前先核对每轮注入的派单状态（已交付/已撤单的活别重办），清单和事实冲突时以事实为准。": "Before acting, check the dispatch status injected each turn (don't redo delivered or withdrawn jobs); when the list and the facts conflict, the facts win.",
  "打开上面那个开关，就能在真实桌面上**双击**放一个组件，或**拖拽框选**一块地方。": "Flip the switch above and you can **double-click** the real desktop to place a component, or **drag to box-select** an area.",
  "② 远程 / 自定义：在「启动命令」里填一条完整命令，ssh 到别的机器也行，例如：": "② Remote / custom: fill a full command into \"start command\" — ssh to another machine works too, e.g.:",
  "（参数 see 开着，但这次没能把图附给你看：压图不可用 —— 别假装看过它。）": "(The see param is on, but this time the image couldn't be attached for you to look at: image compression is unavailable — do not pretend you've seen it.)",
  "（收手势是系统级监听，不铺窗口、不碰桌面本身；组件的删除按钮就在组件上。）": "(The retract gesture is listened for at the system level — no windows are put up and the desktop itself isn't touched; the component's delete button sits on the component.)",
  "这行是明牌：那个可执行文件跟同目录的 snapshot 版本对不上 ——": "This line says it outright: that executable doesn't match the snapshot version sitting next to it —",
  "它现在是一扇独立窗口 —— 主窗口最小化也还在，会一直压在其他程序上面。": "It's now a standalone window — it stays up even when the main window is minimized, and always sits above other programs.",
  "图已经直接发进对话里了（用户能看见，不用你再贴路径）。": "The image has been posted straight into the conversation (the user can see it — you don't need to paste the path).",
  "组件上浮着「收回 / ✕」两个按钮，当场就能拿掉。": "Two buttons float on the component, \"Retract / ✕\" — you can take it away right there.",
  "（这是「别的面板」起的任务，不是你手上的那件）": "(This is a job started by \"another panel\", not the one in your hands)",
  "本轮真正的指令在再下面的用户消息里：": "The real instruction for this turn is in the user message below:",
  "」没搜到 —— 每个源的结果：": "\" wasn't found — results for each source:",
  "图元指令列表。操作类型支持：": "Primitive command list. Supported operation types:",
  "…（更长，去看那块面板）": "... (longer — go look at that panel)",
  "— 换镜像再试也没成 —": "— Tried another mirror and it still failed —",
  "想让我能起它，二选一：": "To let me start it, pick one of two:",
  "（等太久了，已掐断：": "(Waited too long, cut it off:",
  "（一个插件都没找到）": "(No plugins found)",
