  "这次没查出这个解释器里装了什么（下面的状态沿用上次结果）。重进这一页或换一个解释器再试。": "Couldn't list what's installed in this interpreter (status below keeps the last result). Reopen this page or try another interpreter.",
  "关联路径（一行一个或逗号隔开，如 src/pay/、config/pay.json）": "Related paths (one per line or comma-separated, e.g. src/pay/, config/pay.json)",
  "还没有插件。放一个 plugins/&lt;名字&gt;/index.js 就有了。": "No plugins yet. Drop a plugins/<name>/index.js and you're set.",
  "还没有技能。放一个 skills/&lt;名字&gt;/SKILL.md 就有了。": "No skills yet. Drop a skills/<name>/SKILL.md and you're set.",
  "点一下打开这个面板（同一段对话接着往下走）；按住拖到布局里，松在哪儿就开在哪儿": "Click to open this panel (the same conversation continues); hold and drag into the layout — it opens wherever you drop it",
  "[VoiceInput] 选中的麦克风无法访问，降级使用默认麦克风:": "[VoiceInput] Selected microphone is unavailable, falling back to the default microphone:",
  "[VoiceInput] 初始化 VAD 失败，将采用手动停止模式:": "[VoiceInput] VAD init failed, switching to manual stop mode:",
  "正在实时倾听语音中... 说完停顿自动识别上屏（也可随时点击关闭）": "Listening in real time... Pause when you're done and it lands on screen by itself (click to turn it off anytime)",
  "这个面板开着 —— 点一下切过去；按住拖到布局里就是把它挪过去": "This panel is open — click to switch to it; hold and drag into the layout to move it",
  "存在缺失的依赖项，点击右侧按钮通过配置的镜像源自动下载并安装：": "Dependencies are missing — click the button on the right to download and install them from your configured mirror:",
  "Anthropic 开源 MCP 生态支持，自动握手外部服务。": "Anthropic open-source MCP ecosystem support, auto-handshakes with external services.",
  "在软件里直接开网页 —— 看前端、读文档、给别的面板当展示窗。": "Open web pages right inside the app — check frontends, read docs, serve as a display window for other panels.",
