  "智谱": "Zhipu",
  "要改这个软件本身（提示词、面板、插件、工具）时，先读这条，别先翻源码": "When changing this software itself (prompts, panels, plugins, tools), read this first instead of grepping the source",
  "技能和工具都兜不住时，去找\"以前这件事怎么办成的\"——做法散在哪几处、怎么搜、怎么验、成了怎么升格成技能": "When neither skills nor tools cover it: go find how this was done before — which places hold the recipe, how to search, how to verify, and how to promote a working one into a skill",
  "同一个工具连错两次 / 同一步骤卡了两轮 / 用户说\"以前弄过、上次、再来一遍\" / 要动手却发现没有对应技能时": "The same tool failed twice in a row / the same step stalled for two rounds / the user says it was done before, last time, do it again / you are about to start and no matching skill exists",
  "改系统提示词 / 工具表 / 各种「有哪些」清单时的硬约束（保住请求缓存）": "Hard constraints for editing the system prompt, the tool table, or any 'what exists' list (protect the request cache)",
  "要往系统提示里加东西、要增删工具、或要让提示里出现某个动态清单时": "When adding to the system prompt, adding or removing tools, or making a dynamic list show up in the prompt",
  "按需取用的说明。系统提示里只带名字和一句话，助手觉得对得上才用 ": "Notes taken on demand. The system prompt carries only the name and one line; the assistant pulls the body only when it looks like a match with ",
  " —— 所以技能写多长都不占日常开销。": " — so a skill can be as long as it needs to be without costing anything day to day.",
  "技能来自这几个地方（越靠前越优先，重名时前面的赢）——": "Skills come from these places (earlier wins, and on a name clash the earlier one takes it) —",
  "项目自己的技能放进工作区，换项目就跟着换；软件自带的那份一直兜底。": "A project's own skills go in the workspace and follow it when you switch projects; the one built into the app is always the fallback.",
  "（什么时候用：": "（when to use: ",
  "）": "）",
