  "内置的 file-backup 靠这一手，每次改写前自动留底。": "The built-in file-backup works this way: it keeps a copy automatically before every overwrite.",
  "插件改完不用重启：下一次对话就会用新代码。": "No restart needed after editing a plugin: the next conversation uses the new code.",
  "柱子按最大值归一（满格 = 这一段里最大的模型），绝对值写在柱头。": "Bars are normalized to the max (full bar = the biggest model in this segment); the absolute value is written at the top of each bar.",
  "本部门合成时的第二、三段 —— 简介": "The second and third segments when composing for this department — intro",
  "改公司 / 部门 / 角色卡上任意一段，这里自动重算。": "Change any segment on the company / department / agent card and this recalculates automatically.",
  "取消（Esc）": "Cancel (Esc)",
