  "地址里的 ?t= 就是口令 —— 换口令会让旧链接全部作废。": "The ?t= in the address is the passphrase — changing it invalidates all old links.",
  "当前暂无活跃记录，可直接在下方发信开工": "No active records right now; type below to get started",
  "确认打回（不计入工作）": "Confirm send-back (not counted as work)",
  "已验收结案 ·": "Accepted and closed ·",
  "工作区根上有几十个项目，在根上搜等于把这个盘翻一遍：很慢，而且会搜到一堆无关项目。": "There are dozens of projects at the workspace root — searching there means turning the whole drive inside out: slow, and it pulls in a pile of unrelated projects.",
  "插件跑在主进程、画不了界面，所以界面渲染、停靠树、对话本身这些必须住在核心里。": "Plugins run in the main process and can't draw UI, so UI rendering, the dock tree and the conversation itself must live in the core.",
  "上一轮做过的动作会附在对话历史里，**已经读过的文件不要从头再读一遍**。": "Actions from the last turn are attached to the conversation history — **don't re-read an already-read file from the top**.",
  "提案里只写需要变化的字段，没提到的保持原样。JSON 必须合法。": "In a proposal, write only the fields that need to change; anything not mentioned stays as-is. The JSON must be valid.",
  "这个项目为什么这么做 —— 这类东西在输出的时候就圈出来。": "Why this project does things this way — flag this kind of thing when you output it.",
  "反过来，别让表格、列表这类结构退化成纯文本贴出来。": "Conversely, don't let structures like tables and lists degrade into plain text.",
  "又慢又贵 —— 上下文被撑爆主要就是这么来的。": "Slow and expensive — this is how the context mainly gets blown up.",
  "未拆解完整原文": "Full original not broken down",
  "项目事实在 AGENTS.md / CLAUDE.md 里（每轮自动送到你面前，不用自己去读）。": "Project facts live in AGENTS.md / CLAUDE.md (delivered to you automatically every turn; no need to read them yourself).",
  "不要凭印象猜，也不用翻源码确认有哪些。没出现在 tools 里的，就是这一轮没有。": "Do not guess from memory, and no need to read the source to check what exists. Anything not in tools is simply not available this turn.",
  "否则它仍是原来那个类型，你说的话在界面上不会发生。": "Otherwise it stays that same type, and what you say will not take effect in the UI.",
  "重置切片": "Reset slices",
  "工具套件组表。每组 tools 里写**工具的真名字**；写 \"*\" 表示一个都不裁（全量）。": "The tool-kit group table. Each group's tools lists **the real tool names**; write \"*\" to keep every tool (full set).",
