  "插件的 panel.tsx / panel.css）后不用要求用户构建或重启 —— 存盘约 1 秒后它自己跑一次 ": "plugin's panel.tsx / panel.css), there's no need to ask the user to build or restart — about a second after saving it runs itself ",
  "看本机那台模型桥接（默认 127.0.0.1:8317）在不在，不在就把它拉起来 —— ": "Check whether the local model bridge (default 127.0.0.1:8317) is up; if not, bring it up — ",
  " 是一个数组，一项一个控件；卡片照它画，用户改哪个控件就改 hook 里对应的那个字段：": " is an array, one control per item; the card is drawn from it, and whatever control the user changes, change the matching field in hook:",
  "文件名通配过滤，多个用逗号隔开，例如 \"*.ts,*.tsx\" 或 \"*.json\"": "Filename wildcard filter; separate multiple with commas, e.g. \"*.ts,*.tsx\" or \"*.json\"",
  "不要复述代码，不要客套，不要\"好的\"\"总结如下\"这类废话。用简体中文的简洁条目。": "Do not repeat code, do not be polite, do not write filler like \"OK\" or \"summary as follows\". Use concise items in Simplified Chinese.",
  " —— 派单状态为准；你清单里若还挂着这单的条目，把它删掉或标完成。": " — the dispatch status is authoritative; if your list still holds an entry for this dispatch, delete it or mark it done.",
