  "（这是白板上的块到点时说的话。该办就去办，办完不用回报 —— 白板自己记着。）": "(This is what a block on the whiteboard says when its time comes. Do what needs doing — no need to report back, the whiteboard keeps its own records.)",
  "白板上已有的块（要「交给某块面板」时可以对上它们，对不上就别填）：": "Blocks already on the whiteboard (match one of these when you want to \"hand off to a panel\" — if nothing matches, leave it blank):",
