  "阿里开源 SenseVoice-Small 极速离线语音转写，50ms 纯 CPU 本地推理，不联网、无隐私泄露风险。": "Alibaba open-source SenseVoice-Small for ultra-fast offline transcription — 50ms local inference on pure CPU, no network, no privacy risk.",
