  "白板就绪（状态 .ensoul/state/whiteboard.json，指令 .ensoul/state/whiteboard.cmd.json，模板 .ensoul/state/whiteboard.tpl.json，每秒看一次）": "Whiteboard ready (state .ensoul/state/whiteboard.json, commands .ensoul/state/whiteboard.cmd.json, templates .ensoul/state/whiteboard.tpl.json, polled once a second)",
  "这是静默桌面组件。创建时通过 FLOAT_EDIT 将自己改造成有实际内容的组件（不要保留 chat 类型）；不展示聊天、模型配置、日志或默认标题栏。组件业务逻辑优先插件实现；仅在用户明确要求时调用模型。": "This is a silent desktop component. On creation, use FLOAT_EDIT to turn yourself into a component with real content (do not keep the chat type); show no chat, model config, log, or default title bar. Implement component business logic in the plugin first; call the model only when the user explicitly asks.",
  "将当前像素画板导出为清晰无损的 PNG 图片（自动最近邻放大，保证边缘锐利不模糊），并返回文件相对路径。导出后可直接使用 send_image 工具发送到对话中展示。": "Export the current pixel canvas as a crisp lossless PNG (automatic nearest-neighbor upscale, so edges stay sharp and unblurred), and return the file's relative path. After export you can send it straight into the conversation with the send_image tool to display it.",
  "只看一块区域/看缩小版（大画板校对时用）。x/y 起点，w/h 范围，step 每 step×step 个像素合并成 1 个字符（取多数色）。都不填就是整张原尺寸。": "View one region only / a scaled-down version (for proofing a large canvas). x/y = origin, w/h = size, step merges every step×step pixels into 1 character (majority color). Leave all of them empty for the whole image at original size.",
  "把一块面板挂到桌面上，或收回。挂件窗口**没有窗口壳、能透明、常驻置顶** —— 压在所有程序上面，主窗口最小化也不消失，所以能当桌宠 / 桌面时钟 / 状态灯。": "Pin a panel to the desktop, or take it back. A widget window **has no window chrome, can be transparent, and stays on top** — it sits above every program and does not vanish when the main window is minimized, so it works as a desktop pet / desktop clock / status light.",
  "你是白板块的逻辑编译器：把人写的一句话翻成一块「能自己跑、还能在卡片上直接调参」的块定义。只回 JSON，严禁解释、严禁 Markdown 围栏。": "You are the logic compiler for whiteboard blocks: turn one sentence written by a person into a block definition that runs on its own and can be tuned right on the card. Reply with JSON only; explanations are forbidden, Markdown fences are forbidden.",
  "调色板名（pico-8 / gameboy / nes / cyberpunk / pastel）；不给就沿用画板当前调色板": "Palette name (pico-8 / gameboy / nes / cyberpunk / pastel); leave it out to keep the canvas's current palette",
  "现有类型（插件自带）：billing（实时计费）、browser（浏览器）、canvas（无限画布）、dispatch（调度中心）、git（Git）、git-packager（开源打包台）、library（模板库）、our-free-model（Our Free Model）、pixel-canvas（像素画板）、pomodoro（番茄钟）、prompt-manager（提示词管理台）、remote（远程访问）、schedule（定时任务）、star-chart（AI星图）、task-monitor（任务监视器）、tickets（派单队列）、todo（任务清单）、wechat（eschat）、whale-pet（鲸鱼娘桌宠）": "Built-in types (bundled with plugins): billing (real-time billing), browser (browser), canvas (infinite canvas), dispatch (dispatch center), git (Git), git-packager (open-source packager), library (template library), our-free-model (Our Free Model), pixel-canvas (pixel canvas), pomodoro (Pomodoro), prompt-manager (prompt manager), remote (remote access), schedule (scheduled tasks), star-chart (AI star chart), task-monitor (task monitor), tickets (dispatch queue), todo (task list), wechat (eschat), whale-pet (whale-girl desktop pet)",
  "把一张图片直接读进像素网格（图到图）：按画板尺寸做区域平均降采样，再把每个像素量化到调色板里最接近的颜色，可选 Floyd-Steinberg 抖动。用户说\"把这张图画成像素画\"\"这张图转像素\"时用它 —— 不要凭文字描述重画。": "Read an image straight into the pixel grid (image-to-image): area-average downsample to the canvas size, then quantize every pixel to the closest color in the palette, with optional Floyd-Steinberg dithering. Use it when the user says \"把这张图画成像素画\" or \"这张图转像素\" — do not redraw it from a text description.",
  " - manual=不自动动：只等上游把信号送过来，或者用户在卡片上按按钮。凡是不按时间来的块（手动触发、被别的块唤醒）一律用 manual。": " - manual = no automatic action: only wait for the upstream to send a signal, or for the user to press a button on the card. Any block that does not come on a schedule (manual trigger, woken by another block) uses manual.",
  "出图": "Generate image",
